84	/**
85	 * Normalizes a `view_range` array. Returns `undefined` unless the array has
86	 * exactly two integer elements with `startLine >= 0`. `endLine === -1` is
87	 * preserved as the "to end of file" sentinel; otherwise `endLine` must be
88	 * `>= startLine`.
89	 */
90	function formatViewRange(view_range: number[] | undefined): { startLine: number; endLine: number } | undefined {
91		if (!Array.isArray(view_range) || view_range.length !== 2) {
92			return undefined;
93		}
94		const [startLine, endLine] = view_range;
95		if (!Number.isInteger(startLine) || !Number.isInteger(endLine)) {
96			return undefined;
97		}
98		if (startLine < 0) {
99			return undefined;
100		}
101		if (endLine !== -1 && endLine < startLine) {
102			return undefined;
103		}
104		return { startLine, endLine };
105	}
